        },
        {
          "name": "address_type",
          "comment": "类型(shipping/billing)",
          "constraint": ""
        },
        {
          "name": "recipient_first_name",
          "comment": "收件人名",
          "constraint": ""
        },
        {
          "name": "recipient_last_name",
          "comment": "收件人姓",
          "constraint": ""
        },
        {
          "name": "recipient_name",
          "comment": "完整姓名(冗余拼接)",
          "constraint": ""
        },
        {
          "name": "phone_country",
          "comment": "电话区号(+1)",
          "constraint": ""
        },
        {
          "name": "phone_number",
          "comment": "电话号码",
          "constraint": ""
        },
        {
          "name": "alternate_phone_country",
          "comment": "备用电话区号(中东预留)",
          "constraint": ""
        },
        {
          "name": "alternate_phone_number",
          "comment": "备用电话号码(中东预留)",
          "constraint": ""
        },
        {
          "name": "address_line1",
          "comment": "地址行1(街道)",
          "constraint": ""
        },
        {
          "name": "address_line2",
          "comment": "地址行2(公寓)",
          "constraint": ""
        },
        {
          "name": "city",
          "comment": "城市",
          "constraint": ""
        },
        {
          "name": "state_province",
          "comment": "州/省",
          "constraint": ""
        },
        {
          "name": "postal_code",
          "comment": "邮政编码",
          "constraint": ""
        },
        {
          "name": "district",
          "comment": "区/町(亚洲地址预留)",
          "constraint": ""
        },
        {
          "name": "building_name",
          "comment": "建筑名称(日本预留)",
          "constraint": ""
        },
        {
          "name": "is_default",
          "comment": "是否默认地址",
          "constraint": ""
        },
        {
          "name": "place_id",
          "comment": "Google Place ID",
          "constraint": "UNIQUE"
        },
        {
          "name": "latitude",
          "comment": "纬度",
          "constraint": ""
        },
        {
          "name": "longitude",
          "comment": "经度",
          "constraint": ""
        },
        {
          "name": "verified",
          "comment": "是否已验证(V1.1预留)",
          "constraint": ""
        },
        {
          "name": "verified_at",
          "comment": "验证时间",
          "constraint": ""
        },
        {
          "name": "verified_source",
          "comment": "验证来源(google/usps/loqate)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "核心实体，超集字段设计支持多国扩展"
    },
    {
      "name": "delivery_restriction",
      "comment": "配送限制规则",
