        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "merchant_id",
          "comment": "商家ID(NULL=平台级规则)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "restriction_type",
          "comment": "限制类型(po_box/military/custom)",
          "constraint": ""
        },
        {
          "name": "match_field",
          "comment": "匹配字段(address_line1/city等)",
          "constraint": ""
        },
        {
          "name": "match_method",
          "comment": "匹配方式(keyword/regex)",
          "constraint": ""
        },
        {
          "name": "match_pattern",
          "comment": "匹配内容(关键词或正则)",
          "constraint": ""
        },
        {
          "name": "error_message_i18n_key",
          "comment": "买家端提示i18n Key",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "不可配送地址类型规则。merchant_id=NULL为平台级(强制继承)，有值为商家级"
    },
    {
      "name": "address_field_meta",
      "comment": "地址字段元数据",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "field_name",
          "comment": "字段标识(=address表列名)",
          "constraint": "UNIQUE"
        },
        {
          "name": "field_type",
          "comment": "字段类型(text/select/phone)",
          "constraint": ""
        },
        {
          "name": "category",
          "comment": "分类(recipient/address/geo)",
          "constraint": ""
        },
        {
          "name": "display_name",
          "comment": "后台展示名",
          "constraint": ""
        },
        {
          "name": "admin_division_level",
          "comment": "关联行政区划层级(NULL=不关联)",
          "constraint": ""
        },
        {
          "name": "max_length",
          "comment": "数据库列最大长度",
          "constraint": ""
        },
        {
          "name": "description",
          "comment": "后台说明(给运营)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "字段单一事实来源，后台配置/校验规则/前端表单均引用此表"
    },
    {
      "name": "country_address_config",
      "comment": "国家地址配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码(引用market)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "field_config",
          "comment": "字段配置(JSON: enabled)",
          "constraint": ""
        },
        {
          "name": "field_order",
          "comment": "字段顺序(JSON)",
          "constraint": ""
        },
        {
          "name": "field_i18n_keys",
          "comment": "字段国际化文案Key(JSON)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "定义各国地址字段的可见性、必填性和顺序"
    },
    {
      "name": "address_field_validation_rules",
      "comment": "地址字段校验规则",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "field_name",
          "comment": "字段名(引用registry)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "rule_type",
          "comment": "规则类型(pattern/length/custom)",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "执行优先级(值小先执行)",
          "constraint": ""
        },
        {
          "name": "pattern",
          "comment": "正则表达式(pattern/custom时使用)",
          "constraint": ""
        },
        {
          "name": "min_length",
          "comment": "最小长度(length时使用)",
          "constraint": ""
        },
        {
          "name": "max_length",
          "comment": "最大长度(length时使用)",
          "constraint": ""
        },
        {
          "name": "execute_on",
          "comment": "执行端(client/server/both)",
          "constraint": ""
        },
        {
          "name": "severity",
          "comment": "严重程度(error/warning)",
          "constraint": ""
        },
        {
          "name": "required_level",
          "comment": "必填性(required/optional/conditional)",
          "constraint": ""
        },
        {
          "name": "error_message_i18n_key",
          "comment": "多语言key",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "技术校验(格式/长度)，按priority顺序执行。唯一约束: (country_code, field_name, rule_type, priority)"
    },
    {
      "name": "administrative_division",
      "comment": "行政区划层级",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "level",
          "comment": "层级(1=州/省 2=市 3=区)",
          "constraint": ""
        },
        {
          "name": "code",
          "comment": "行政区划代码",
          "constraint": "UNIQUE"
        },
        {
          "name": "name",
          "comment": "名称",
          "constraint": ""
        },
        {
          "name": "name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "parent_id",
          "comment": "父级ID(自引用)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "各国行政区划树形数据(州/市/区)，支撑下拉选择。数据通过批量导入维护"
    },
    {
      "name": "postal_code_mapping",
      "comment": "邮编映射表",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "postal_code",
          "comment": "邮政编码",
          "constraint": "UNIQUE"
        },
        {
          "name": "city",
          "comment": "城市",
          "constraint": ""
        },
        {
          "name": "state_code",
          "comment": "州/省代码",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "邮编→城市/州反查，前端用于城市/州/邮编联动校验。导入时校验state_code须存在于administrative_division(level=1)"
    },
    {
      "name": "user",
      "comment": "用户(外部)",
      "columns": [
        {
          "name": "id",
          "comment": "用户ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "email",
          "comment": "邮箱",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "账户状态",
          "constraint": ""
        }
      ],
      "note": "用户模块提供，地址库引用user_id"
    },
    {
      "name": "country",
      "comment": "国家(market模块)",
      "columns": [
        {
          "name": "country_code",
          "comment": "ISO 3166-1 alpha-2",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name",
          "comment": "国家名称",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "货币代码",
          "constraint": ""
        }
      ],
      "note": "MARKET模块提供，地址库引用country_code"
    },
    {
      "name": "merchant",
      "comment": "商家(外部)",
      "columns": [
        {
          "name": "id",
          "comment": "商家ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name",
          "comment": "商家名称",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "商家状态",
          "constraint": ""
        }
      ],
      "note": "商家模块提供，配送限制引用merchant_id。自营阶段merchant_id留空"
    }
  ],
  "relations": [
    {
      "from": "user",
      "to": "address",
      "type": "1:N",
      "label": "拥有多个地址",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "country",
      "to": "address",
      "type": "1:N",
      "label": "地址所属国家",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "country_address_config",
      "type": "1:1",
      "label": "国家字段配置",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "address_field_validation_rules",
      "type": "1:N",
      "label": "校验规则(按国家)",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "postal_code_mapping",
      "type": "1:N",
      "label": "邮编数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "administrative_division",
      "type": "1:N",
      "label": "行政区划数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "administrative_division",
      "to": "administrative_division",
      "type": "1:N",
      "label": "父子层级(自引用)",
      "color": "#E8833A",
      "penwidth": 1.2,
      "style": "dashed"
    },
    {
      "from": "address_field_meta",
      "to": "country_address_config",
      "type": "1:N",
      "label": "field_config引用字段元数据",
      "color": "#2E7D32",
      "penwidth": 1.4,
      "style": "dashed"
    },
    {
      "from": "address_field_meta",
      "to": "address_field_validation_rules",
      "type": "1:N",
      "label": "field_name引用元数据",
      "color": "#2E7D32",
      "penwidth": 1.4
    },
    {
      "from": "merchant",
      "to": "delivery_restriction",
      "type": "1:N",
      "label": "商家配送限制",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "delivery_restriction",
      "type": "1:N",
      "label": "国家配送限制",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "address_field_meta",
      "to": "administrative_division",
      "type": "1:N",
      "label": "admin_division_level映射",
      "color": "#2E7D32",
      "penwidth": 1.2,
      "style": "dashed"
    }
  ],
  "design_rules": {
    "superset_fields": "超集字段设计：数据库包含所有国家字段，通过country_address_config控制展示",
    "field_registry": "address_field_meta是字段的单一事实来源，后台配置页从此表读取可选字段列表",
    "admin_division_mapping": "admin_division_level数据驱动行政区划映射：state_province→L1, city→L2, district→L3，不硬编码",
    "market_integration": "国家可用性引用market模块，地址库不独立维护国家列表",
    "frontend_i18n": "前端多语言采用i18n方案，数据库不存储多语言字段",
    "name_split": "recipient_first_name + recipient_last_name 拆分存储，支持支付AVS和物流API",
    "name_concat": "recipient_name 冗余存储拼接结果，拼接顺序由country_address_config.name_format控制",
    "address_type_enum": "address_type 枚举值: shipping, billing",
    "verified_source_enum": "verified_source 枚举值: google, usps, loqate",
    "soft_delete": "地址数据支持软删除(CCPA要求可彻底删除)",
    "encryption": "phone_number, recipient_first_name, recipient_last_name 字段 AES-256 加密存储",
    "place_id_dedup": "通过 place_id 做地址去重(V1.1)",
    "mvp_scope": "MVP只启用美国(US)，预留字段: alternate_phone_*, district, building_name, verified_*",
    "snapshot_ownership": "订单地址快照(order_address_snapshot)由订单模块管理，不在地址库ER图中体现",
    "validation_execute_on": "execute_on区分前后端：client=前端实时校验, server=后端提交校验, both=前后端都执行",
    "validation_severity": "severity区分拦截级别：error=硬拦截阻止保存, warning=软提示允许继续",
    "multi_rule_validation": "同一字段支持多条校验规则，按priority顺序执行，命中首个失败即返回对应error_message",
    "rule_type_enum": "rule_type 枚举值: pattern(正则格式), length(长度范围), custom(自定义正则)",
    "required_level_in_rules": "required_level 统一在 address_field_validation_rules 中管理，枚举值: required/optional/conditional。field_config 不再承载必填性",
    "field_config_structure": "field_config JSON结构: {field_name: {enabled: bool}}，enabled=是否在该国启用此字段。field_name必须存在于address_field_meta",
    "error_message_i18n_only": "校验规则错误提示统一使用 error_message_i18n_key，不存储硬编码文案，前端按key渲染多语言",
    "merchant_isolation": "配送限制支持多商家隔离：merchant_id=NULL为平台级规则(所有商家强制继承)，有值为商家级规则(仅该商家生效)",
    "delivery_restriction_scope": "地址校验时取并集：平台规则 ∪ 商家规则，命中任一即拦截。商家不能覆盖或绕过平台级规则",
    "public_data_ownership": "公共数据(国家地址配置/行政区划/邮编)由超级管理员维护，不区分商家。配送限制支持商家自主配置",
    "mvp_merchant_strategy": "MVP阶段Looply自营，delivery_restriction.merchant_id全部为NULL(等同平台级)。后续引入商家时只需加筛选和权限控制"
  }
}
